<?php
require __DIR__.'/../includes/new-common.php';
$id=(int)($_GET['id']??0);$stmt=$pdo->prepare('SELECT * FROM eco_lists WHERE id=?');$stmt->execute([$id]);$list=$stmt->fetch();if(!$list){http_response_code(404);exit('Lista nu există.');}
$rate=eco_rate();$error='';$success=false;
if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf_check();try{
  $r=(float)($rate['rate']??0);$manual=(float)str_replace(',','.',(string)($_POST['manual_rate']??''));if($manual>=3&&$manual<=8)$r=$manual;
  if($r<=0)throw new RuntimeException('Introdu cursul EUR/RON verificat pentru recalcularea prețurilor.');
  $tierMap=eco_tiers_map($pdo,array_map(fn($k)=>['id'=>(int)$k],array_keys($_POST['products']??[])));
  $stmt=$pdo->prepare('UPDATE eco_list_products SET reference=?,name=?,price_eur=?,price_ron=?,exchange_rate=?,on_site=?,checked_at=?,notes=? WHERE id=? AND list_id=?');
  $pdo->beginTransaction();foreach(($_POST['products']??[]) as $pid=>$v){$name=trim((string)($v['name']??''));if(!$name)throw new RuntimeException('Denumirea produsului este obligatorie.');$eur=max(0,(float)str_replace(',','.',(string)($v['price_eur']??0)));if(!empty($tierMap[(int)$pid]))$eur=(float)$tierMap[(int)$pid][0]['price_eur'];$date=trim((string)($v['checked_at']??''));if($date!==''&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))throw new RuntimeException('Data actualizării este invalidă.');$stmt->execute([trim((string)($v['reference']??'')),$name,$eur,round($eur*$r,2),$r,isset($v['on_site'])?1:0,$date?:null,trim((string)($v['notes']??'')),(int)$pid,$id]);} $pdo->commit();$success=true;
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}
}
$stmt=$pdo->prepare('SELECT * FROM eco_list_products WHERE list_id=? ORDER BY sort_order,id');$stmt->execute([$id]);$products=$stmt->fetchAll();$tierMap=eco_tiers_map($pdo,$products);require __DIR__.'/../includes/header.php';?>
<div class="eco-heading"><div><a class="eco-back" href="/lists/">← Liste produse</a><h1><?=e($list['name'])?> · Actualizare rapidă</h1><p>Editează toate produsele direct în tabel și salvează modificările împreună.</p></div><a class="eco-button eco-button-light" href="/lists/edit.php?id=<?=$id?>#product-editor">+ Adaugă produs</a></div>
<?php if($error):?><div class="eco-error"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="eco-success">Modificările au fost salvate.</div><?php endif;?>
<form method="post" id="bulkForm"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><div class="eco-panel"><div class="eco-heading"><h2><?=count($products)?> produse</h2><p>Curs: <strong><?=!empty($rate['rate'])?number_format($rate['rate'],4,',','.').' RON':'indisponibil'?></strong> · <?=e($rate['date']??'—')?></p></div><label style="max-width:360px;display:block">Curs manual EUR/RON (opțional)<input type="number" name="manual_rate" id="bulkRate" min="3" max="8" step="0.0001" placeholder="Ex. 5.0000"></label><div class="eco-table-scroll"><table class="eco-table eco-bulk-table"><thead><tr><th>Referință</th><th>Produs</th><th>EUR</th><th>RON automat</th><th>Actualizat pe site</th><th>Data actualizării</th><th>Observații</th></tr></thead><tbody><?php foreach($products as $x):$n='products['.(int)$x['id'].']';?><tr><td><input name="<?=$n?>[reference]" value="<?=e($x['reference'])?>" aria-label="Referință"></td><td><input name="<?=$n?>[name]" value="<?=e($x['name'])?>" required aria-label="Denumire produs"></td><td><?php if(!empty($tierMap[$x['id']])):?><small>Pragurile se editează din fișa produsului.</small><br><a href="/lists/edit.php?id=<?=$id?>&product=<?=$x['id']?>#product-editor">Editează praguri</a><?php endif;?><input class="bulk-eur" type="number" min="0" step="0.01" name="<?=$n?>[price_eur]" value="<?=e((string)$x['price_eur'])?>" <?=!empty($tierMap[$x['id']])?'readonly':''?>></td><td><output class="bulk-ron" data-old="<?=e((string)$x['price_ron'])?>"></output></td><td><label class="eco-bulk-check"><input type="checkbox" name="<?=$n?>[on_site]" value="1" <?=$x['on_site']?'checked':''?>><span>Da</span></label></td><td><input type="date" name="<?=$n?>[checked_at]" value="<?=e((string)$x['checked_at'])?>"></td><td><textarea name="<?=$n?>[notes]" rows="2"><?=e($x['notes'])?></textarea></td></tr><?php endforeach;?></tbody></table></div><?php if(!$products):?><p>Lista este goală. Adaugă primul produs din editorul separat.</p><?php endif;?></div><div class="eco-sticky-actions"><button class="eco-button" type="submit">Salvează toate modificările</button><button class="eco-button eco-button-light" type="button" id="markToday">Setează data de azi la produsele bifate</button></div></form>
<script>(()=>{const base=<?=json_encode((float)($rate['rate']??0))?>,rate=document.getElementById('bulkRate'),table=document.querySelector('.eco-bulk-table');function update(){const r=Number(rate.value)||base;table.querySelectorAll('tbody tr').forEach(row=>{const eur=Number(row.querySelector('.bulk-eur').value)||0,out=row.querySelector('.bulk-ron');out.textContent=r>0?(eur*r).toLocaleString('ro-RO',{minimumFractionDigits:2,maximumFractionDigits:2})+' RON':Number(out.dataset.old).toLocaleString('ro-RO',{minimumFractionDigits:2})+' RON';});}table.addEventListener('input',update);rate.addEventListener('input',update);update();document.getElementById('markToday').onclick=()=>{const d=new Date(),today=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');table.querySelectorAll('tbody tr').forEach(row=>{if(row.querySelector('input[type=checkbox]').checked)row.querySelector('input[type=date]').value=today;});};})();</script>
